parameters.jsCode:
// Settings for this workflow (chat ID, Notion IDs, hours). Other nodes read
// $('Config').first().json; the build injects config/config.local.json here.
// @inject config as CONFIG
// @end-inject

return [{ json: CONFIG }];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "free_minutes": {
      "type": "integer",
      "description": "Free working minutes today after meetings and buffers"
    },
    "planned_minutes": {
      "type": "integer",
      "description": "Sum of estimates of the tasks in today"
    },
    "overloaded": {
      "type": "boolean",
      "description": "true when open work that matters did not fit into today"
    },
    "meetings": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "One line per meeting, e.g. \"10:00–11:00 · Standup\""
    },
    "today": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string"
          },
          "title": {
            "type": "string"
          },
          "priority": {
            "type": "string"
          },
          "estimate_min": {
            "type": "integer"
          },
          "slot": {
            "type": "string",
            "description": "Suggested start time HH:MM inside a free slot"
          }
        },
        "required": [
          "id",
          "title",
          "priority",
          "estimate_min",
          "slot"
        ],
        "additionalProperties": false
      }
    },
    "move": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string"
          },
          "title": {
            "type": "string"
          },
          "reason": {
            "type": "string"
          },
          "new_date": {
            "type": "string",
            "description": "YYYY-MM-DD, a working day"
          }
        },
        "required": [
          "id",
          "title",
          "reason",
          "new_date"
        ],
        "additionalProperties": false
      }
    },
    "risks": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string"
          },
          "title": {
            "type": "string"
          },
          "reason": {
            "type": "string"
          }
        },
        "required": [
          "id",
          "title",
          "reason"
        ],
        "additionalProperties": false
      }
    },
    "fyi": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string"
          },
          "title": {
            "type": "string"
          }
        },
        "required": [
          "id",
          "title"
        ],
        "additionalProperties": false
      }
    },
    "note": {
      "type": "string",
      "description": "One sentence on how the day looks"
    },
    "telegram_html": {
      "type": "string",
      "description": "The whole digest as Telegram HTML, under 3500 characters"
    },
    "digest_markdown": {
      "type": "string",
      "description": "The same digest as Markdown for the Notion page"
    }
  },
  "required": [
    "free_minutes",
    "planned_minutes",
    "overloaded",
    "meetings",
    "today",
    "move",
    "risks",
    "fyi",
    "note",
    "telegram_html",
    "digest_markdown"
  ],
  "additionalProperties": false
}
